import localFont from "next/font/local";

/**
 * V3 typefaces — the approved variable woff2 files from the design handoff
 * (design-handoff/fonts/, OFL texts alongside). See docs/design/V3-DESIGN-SOURCE.md §4.
 *
 * - Weight/stretch ranges mirror prototype.css so the browser drives the
 *   variable axes instead of synthesising bold/condensed faces.
 * - Family names are generated by next/font from the constant names
 *   (`bricolage`, `atkinson`, `fredoka`); tests assert them.
 * - display: swap (PROMPT.md overrides the prototype's `block`). Bricolage and
 *   Atkinson roman are preloaded; the Atkinson italic and Fredoka (accent only)
 *   are not, because `preload` applies to every file a call loads.
 */
export const bricolage = localFont({
  src: "./fonts/BricolageGrotesque-Variable.woff2",
  weight: "200 800",
  display: "swap",
  variable: "--ff-bricolage",
  declarations: [{ prop: "font-stretch", value: "75% 100%" }],
});

export const atkinson = localFont({
  src: "./fonts/AtkinsonHyperlegibleNext-Variable.woff2",
  weight: "200 800",
  style: "normal",
  display: "swap",
  variable: "--ff-atkinson",
});

// Declared under the `atkinson` family so `font-style: italic` resolves to this
// face, without preloading it (preload is per call).
export const atkinsonItalic = localFont({
  src: "./fonts/AtkinsonHyperlegibleNext-Variable-Italic.woff2",
  weight: "200 800",
  style: "italic",
  display: "swap",
  preload: false,
  // Only a variable is applied (never className, which would italicise the page).
  variable: "--ff-atkinson-italic",
  declarations: [{ prop: "font-family", value: "atkinson" }],
});

export const fredoka = localFont({
  src: "./fonts/Fredoka-Variable.woff2",
  weight: "300 700",
  display: "swap",
  preload: false,
  variable: "--ff-fredoka",
});

export const fontVariables = [
  bricolage.variable,
  atkinson.variable,
  atkinsonItalic.variable,
  fredoka.variable,
].join(" ");
